def generate(seed):
    r = random.Random(seed)
    n = r.randint(6, 9)
    a = [r.randint(3, 60) for _ in range(n)]
    while True:
        m = [r.randint(0, 1) for _ in range(n)]
        if any(m) and not all(m):
            break
    t = sum(v for v, b in zip(a, m) if b)
    return ' '.join(str(v) for v in a) + '|' + str(t)

