def solve(clue):
    a, t = clue.split('|')
    a = [int(x) for x in a.split()]
    t = int(t)
    n = len(a)
    for m in range(1, 1 << n):
        if sum(a[i] for i in range(n) if m >> i & 1) == t:
            return ''.join('1' if m >> i & 1 else '0' for i in range(n))
    return ''

